export function syncF4TrapView(b, f, at, h, m) {
  m.state = syncTrState(b, f, at + 0, h, m.state ?? new TrStateMirror());
  m.attacker = syncAttacker(b, f, at + 9, h, m.attacker);
  return m;
}

export function putF4TrapView(b, o, f, at, heap) {
  putTrState(b, o.state, f, at + 0, heap);
  putAttacker(b, o.attacker, f, at + 9, heap);
}

export function sameF4TrapView(a, b) {
  { const d = sameTrState(a.state, b.state); if (d) return ".state" + d; }
  if (!sameAttacker(a.attacker, b.attacker)) return ".attacker";
  return null;
}

export function exportF4TrapView(o, cx) {
  let v = cx.seen.get(o);
  if (v) return v;
  v = {};
  cx.seen.set(o, v);
  v.state = exportTrState(o.state, cx);
  v.attacker = exportAttacker(o.attacker, cx);
  return v;
}
